#include <string>
#include <utility>
#include <vector>

class Profile {
public:
    void set_name(std::string n) { name_ = std::move(n); }   // KEEPS: by value + move.
    const std::string& name() const { return name_; }
private:
    std::string name_;
};

int total(const std::vector<int>& v) {        // READS: const reference, no copy.
    int sum = 0;
    for (int x : v) sum += x;                  // int is small: copy is fine.
    return sum;
}

void add_bonus(std::vector<int>& v, int bonus) {   // MODIFIES: reference.
    for (int& x : v) x += bonus;
}

void log_to(const std::string& msg, std::string* extra = nullptr) {  // OPTIONAL: pointer.
    if (extra) *extra += msg;
}
```

| Intent | Form |
|---|---|
| small value (int, double). | `T`. |
| read a large object. | `const T&`. |
| modify the caller's object. | `T&`. |
| keep a copy (sink). | `T` then `std::move`. |
| optional, may be absent. | `T*` (or `std::optional<T>` for values). |

